// planningDescribedBy combines a field's optional hint ID (e.g. a resolved
// timezone span) with its validation-error ID, if any, into the single
// space-separated token list aria-describedby expects.
func planningDescribedBy(errors FormErrors, fieldID, hintID string) string {
	describedBy := hintID
	if errors.Message(fieldID) != "" {
		if describedBy != "" {
			describedBy += " "
		}
		describedBy += fieldID + "-error"
	}
	return describedBy
}

// planningZoneID names the hint span reporting the resolved timezone for a
// datetime-local input, so the input's aria-describedby can reach it.
func planningZoneID(target string, id int, field string) string {
	return PlanningFieldID(target, id, field) + "-zone"
}

